import re, unittest
def valid_id(text):
    return re.fullmatch(r"[a-z][a-z0-9]{2,7}", text) is not None
class IdTests(unittest.TestCase):
    def test_boundaries(self):
        for s in ["abc", "a12", "abcdefgh"]:
            self.assertTrue(valid_id(s), s)
        for s in ["ab", "abcdefghi", "1ab", "abc!"]:
            self.assertFalse(valid_id(s), s)
if __name__ == "__main__":
    unittest.main()
